"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { createClient } from "@/lib/supabase/client";

function GoogleIcon() {
  return (
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M17.64 9.20455C17.64 8.56636 17.5827 7.95273 17.4764 7.36364H9V10.845H13.8436C13.635 11.97 13.0009 12.9232 12.0477 13.5614V15.8195H14.9564C16.6582 14.2527 17.64 11.9455 17.64 9.20455Z" fill="#4285F4"/>
                  <path d="M9 18C11.43 18 13.4673 17.1941 14.9564 15.8195L12.0477 13.5614C11.2418 14.1014 10.2109 14.4204 9 14.4204C6.65591 14.4204 4.67182 12.8373 3.96409 10.71H0.957275V13.0418C2.43818 15.9832 5.48182 18 9 18Z" fill="#34A853"/>
                        <path d="M3.96409 10.71C3.78409 10.17 3.68182 9.59318 3.68182 9C3.68182 8.40682 3.78409 7.83 3.96409 7.29V4.95818H0.957275C0.347727 6.17318 0 7.54773 0 9C0 10.4523 0.347727 11.8268 0.957275 13.0418L3.96409 10.71Z" fill="#FBBC05"/>
                              <path d="M9 3.57955C10.3214 3.57955 11.5077 4.03364 12.4405 4.92545L15.0218 2.34409C13.4632 0.891818 11.4259 0 9 0C5.48182 0 2.43818 2.01682 0.957275 4.95818L3.96409 7.29C4.67182 5.16273 6.65591 3.57955 9 3.57955Z" fill="#EA4335"/>
                                  </svg>
                                    );
                                    }

                                    export default function SignupPage() {
                                      const router = useRouter();
                                        const [name, setName] = useState("");
                                          const [email, setEmail] = useState("");
                                            const [password, setPassword] = useState("");
                                              const [error, setError] = useState<string | null>(null);
                                                const [success, setSuccess] = useState(false);
                                                  const [loading, setLoading] = useState(false);
                                                    const [googleLoading, setGoogleLoading] = useState(false);

                                                      async function handleGoogle() {
                                                          setGoogleLoading(true);
                                                              const supabase = createClient();
                                                                  await supabase.auth.signInWithOAuth({
                                                                        provider: "google",
                                                                              options: { redirectTo: `${window.location.origin}/auth/callback` },
                                                                                  });
                                                                                    }

                                                                                      async function handleSubmit(e: React.FormEvent) {
                                                                                          e.preventDefault();
                                                                                              setLoading(true);
                                                                                                  setError(null);
                                                                                                      const supabase = createClient();
                                                                                                          const { error } = await supabase.auth.signUp({
                                                                                                                email,
                                                                                                                      password,
                                                                                                                            options: {
                                                                                                                                    data: { full_name: name },
                                                                                                                                            emailRedirectTo: `${window.location.origin}/auth/callback`,
                                                                                                                                                  },
                                                                                                                                                      });
                                                                                                                                                          setLoading(false);
                                                                                                                                                              if (error) {
                                                                                                                                                                    setError(error.message);
                                                                                                                                                                          return;
                                                                                                                                                                              }
                                                                                                                                                                                  setSuccess(true);
                                                                                                                                                                                    }

                                                                                                                                                                                      if (success) {
                                                                                                                                                                                          return (
                                                                                                                                                                                                <div>
                                                                                                                                                                                                        <div className="text-xs uppercase tracking-[0.3em] text-copper mb-4 font-mono">§ Confirmacao</div>
                                                                                                                                                                                                                <h1 className="font-display text-4xl mb-4 leading-tight" style={{ fontWeight: 300 }}>
                                                                                                                                                                                                                          Conta criada. ✦
                                                                                                                                                                                                                                  </h1>
                                                                                                                                                                                                                                          <p className="text-bone-dim mb-8 leading-relaxed">
                                                                                                                                                                                                                                                    Mandamos um e-mail de confirmacao para <strong className="text-bone">{email}</strong>. Clique no link e voce esta dentro.
                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                    <Link href="/login" className="block text-center w-full py-3 bg-bone text-ink font-medium hover:bg-copper transition">
                                                                                                                                                                                                                                                                              Voltar ao login
                                                                                                                                                                                                                                                                                      </Link>
                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                              <div className="text-xs uppercase tracking-[0.3em] text-copper mb-4 font-mono">§ Criar conta</div>
                                                                                                                                                                                                                                                                                                                    <h1 className="font-display text-4xl mb-2 leading-tight" style={{ fontWeight: 300 }}>
                                                                                                                                                                                                                                                                                                                            Cinco creditos gratis.
                                                                                                                                                                                                                                                                                                                                  </h1>
                                                                                                                                                                                                                                                                                                                                        <p className="text-bone-dim mb-8">Sem cartao. Sem cadastro de cobranca.</p>

                                                                                                                                                                                                                                                                                                                                              <button
                                                                                                                                                                                                                                                                                                                                                      type="button"
                                                                                                                                                                                                                                                                                                                                                              onClick={handleGoogle}
                                                                                                                                                                                                                                                                                                                                                                      disabled={googleLoading}
                                                                                                                                                                                                                                                                                                                                                                              className="w-full mb-4 py-3 border border-ink-line hover:border-copper transition flex items-center justify-center gap-3 text-sm disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                            <GoogleIcon />
                                                                                                                                                                                                                                                                                                                                                                                                    {googleLoading ? "Redirecionando..." : "Criar conta com Google"}
                                                                                                                                                                                                                                                                                                                                                                                                          </button>

                                                                                                                                                                                                                                                                                                                                                                                                                <div className="flex items-center gap-3 mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex-1 h-px bg-ink-line" />
                                                                                                                                                                                                                                                                                                                                                                                                                                <span className="text-xs text-bone-dim font-mono">ou</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex-1 h-px bg-ink-line" />
                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                    <form onSubmit={handleSubmit} className="space-y-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label className="block text-xs uppercase tracking-[0.2em] text-bone-dim mb-2 font-mono">Nome</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setName(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="w-full bg-ink-deep border border-ink-line px-4 py-3 text-bone focus:border-copper focus:outline-none transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="block text-xs uppercase tracking-[0.2em] text-bone-dim mb-2 font-mono">E-mail</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full bg-ink-deep border border-ink-line px-4 py-3 text-bone focus:border-copper focus:outline-none transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="block text-xs uppercase tracking-[0.2em] text-bone-dim mb-2 font-mono">Senha</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        minLength={8}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    value={password}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setPassword(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="w-full bg-ink-deep border border-ink-line px-4 py-3 text-bone focus:border-copper focus:outline-none transition"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-xs text-bone-dim mt-2">Minimo 8 caracteres.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {error && <p className="text-sm text-copper-deep">{error}</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="submit"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            disabled={loading}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full py-3 bg-bone text-ink font-medium hover:bg-copper transition disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {loading ? "Criando..." : "Criar conta gratis"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="text-xs text-bone-dim text-center leading-relaxed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Ao criar conta voce concorda com nossos{" "}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Link href="/terms" className="text-copper hover:underline">termos</Link> e{" "}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Link href="/privacy" className="text-copper hover:underline">politica de privacidade</Link>.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </form>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="mt-8 text-sm text-bone-dim text-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Ja tem conta?{" "}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Link href="/login" className="text-copper hover:underline">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Entrar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }